const encrypt = (s) => {
    let outputString = '';
    let alphabet = 'abcdefghijklmnopqrstuvwxyz';
    let inputArr = s.split('');
    let lastIndex = alphabet.length - 1;
    inputArr.forEach(function(inputChar){
        let inputCharIndex = alphabet.indexOf(inputChar);
        if(inputCharIndex === lastIndex){
            let shiftedIndex = inputCharIndex - lastIndex;
            outputString += alphabet[shiftedIndex];
        }else if(inputCharIndex === lastIndex - 1){
            let shiftedIndex = inputCharIndex - lastIndex + 1;
            outputString += alphabet[shiftedIndex];
        }else{
            let shiftedIndex = inputCharIndex + 2;
            outputString += alphabet[shiftedIndex];
        }
    });
    return outputString;
}

