    var lower = s.toLowerCase();
    var length = lower.length;
    var newString = '';
    for(var i = 0; i < length; i++){
        var index = alphabet.indexOf(lower[i]);
        if(index < 0){
            newString += lower[i];
        }
        else{
            var newIndex = index + 2 * 2;
            if(newIndex > 25){
