    if(arr.length === 0) return true;
    var res = [...arr].sort((a,b)=>a-b);
    var count = 0;
    var map = new Map();
    arr.forEach(v=>{
        if(!map.has(v))
            map.set(v, 1);
        else
            map.set(v, map.get(v)+1);
    });
    for(var i=0; i<arr.length; i++){
        var val = arr[i];
        var expected_val = res[i];
        if(val !== expected_val){
            var c1 = map.get(val);
            var c2 = map.get(expected_val);
            var change = c1 - c2;
            if(change < 0)
                return false;
            map.set(val, c1-c2);
            map.set(expected_val, 0);
            count += change;
        }
    }
    return count < 2;
}

