    // get count of the highest number in the list
  let highestNum = Math.max(...lst);
  //count the frequency of the highest number in the list
  let numCount = 0;
  for (let i = 0; i < lst.length; i++) {
    if (lst[i] === highestNum) {
      numCount++;
    }
  }
  // the value of the frequency must be greater than or equal to the value of the highest number
  if (numCount >= highestNum) {
    return highestNum;
  } else {
    return -1;
  }
}

