const search = (lst) => {
    var sortedList = lst.sort(function(a, b){return a-b});
    for (var i = 0; i < sortedList.length; i++) {
        if (sortedList[i] === sortedList[i+1]) {
            var item = sortedList[i];
            var counter = 0;
            var index = sortedList.indexOf(item);
            while (index != -1) {
                counter++;
                index = sortedList.indexOf(item, index + 1);
            }
            if (counter >= item) {
                return item;
            }
        }
    }
    return -1;
}

