const findClosestElements = (numbers) => {
    // First grab the array length.
    var array_length = numbers.length;
    // Create a variable to hold the closest numbers.
    var closest_numbers = [0, 0];
    // Start the closest_diff at infinity.
    var closest_diff = Number.POSITIVE_INFINITY;
    // Loop through each number.
    for (var i = 0; i < array_length; i++){
        // Grab the current number.
        var current_number = numbers[i];
        // If the current number is the last number in the array, skip it.
        if (i === array_length - 1){
            break;
        }
        // Otherwise grab the next number in the array.
        var next_number = numbers[i + 1];
        // Calculate the current difference between the two numbers.
        var current_diff = Math.abs(current_number - next_number);
        // If the current difference is less than the closest_diff, make it the new closest_diff,
        // and set the closest_numbers to these two numbers.
        if (current_diff < closest_diff){
            closest_diff = current_diff;
            closest_numbers = [current_number, next_number];
        }
    }
    // Return the closest_numbers.
    return closest_numbers;
}

