const findClosestElements = (numbers) => {
    if(!Array.isArray(numbers)){
        throw new Error("Parameter must be an array");
    }
    if(numbers.length < 2){
        throw new Error("Parameter must have at least two elements");
    }
    var minDiff = Math.abs(numbers[0] - numbers[1]);
    var minIndexes = [0, 1];
    for(var i = 0; i < numbers.length - 1; i++){
        var diff = Math.abs(numbers[i] - numbers[i + 1]);
        if(diff < minDiff){
            minDiff = diff;
            minIndexes = [i, i + 1];
        }
    }
    var smaller = numbers[minIndexes[0]];
    var larger = numbers[minIndexes[1]];
    if(larger < smaller){
        smaller = numbers[minIndexes[1]];
        larger = numbers[minIndexes[0]];
    }
    return {
        smaller: smaller,
        larger: larger
    };
}

