    var is_increasing = true;
  var is_decreasing = true;
  var last_num = l[0];
  var i = 1;
  while (i < l.length){
    if (last_num > l[i]){
      is_increasing = false;
    }
    if (last_num < l[i]){
      is_decreasing = false;
    }
    last_num = l[i];
    i++;
  }
  return is_increasing || is_decreasing;
}

