        } else if (digits[i] == 4) {
            result += numerals[1*Math.pow(10, digits.length-i-1)] + numerals[5*Math.pow(10, digits.length-i-1)];
        } else {
            result += numerals[1*Math.pow(10, digits.length-i-1)].repeat(digits[i]);
        }
    }
    return result;
}

