const sortArray = (arr) => {
    //binary_arr holds binary array, binary_sort_arr holds sorted binary array
  //decimal_arr holds the decimal values in sorted binary order
  var binary_arr = [], binary_sort_arr = [], decimal_arr = [], sorted_arr = [];
  //go through every element in array
  for(var i = 0; i < arr.length; i++){
    //convert the number to binary and store into binary_arr
    binary_arr.push(arr[i].toString(2));
    //check for one's count in binary_arr[i] and push the count into binary_sort_arr
    binary_sort_arr.push(binary_arr[i].match(/1/g).length);
  }
  //sort the binary_sort_arr
  binary_sort_arr.sort(function(a, b){return a - b});
  //fill decimal_arr with the sorted binary numbers
  for(var i = 0; i < binary_sort_arr.length; i++){
    for(var j = 0; j < binary_arr.length; j++){
      if(binary_sort_arr[i] == binary_arr[j].match(/1/g).length && !decimal_arr.includes(binary_arr[j])){
        decimal_arr.push(binary_arr[j]);
      }
    }
  }
  //convert the binary to decimal and store into sorted_arr
  for(var i = 0; i < decimal_arr.length; i++){
    sorted_arr.push(parseInt(decimal_arr[i], 2));
  }
  return sorted_arr;
}
