const sortArray = (arr) => {
    var maxOnes = 0;
    var minOnes = 0;
    var temp = [];
    var tempArr = [];
    var tempObj = {};
    var count;
    var maxInt;
    var newArr = [];
    var result = [];
    if(arr.length > 1){
        maxInt = Math.max.apply(null, arr);
        count = (maxInt >>> 0).toString(2).split('').length;
        for(var i = 0; i < arr.length; i++){
            temp = (arr[i] >>> 0).toString(2).split('');
            while(temp.length < count){
                temp.unshift('0');
            }
            tempObj = {};
            tempObj.num = arr[i];
            tempObj.ones = temp.join('').split('1').length - 1;
            if(tempObj.ones > maxOnes){
                maxOnes = tempObj.ones;
            }
            if(tempObj.ones < minOnes){
                minOnes = tempObj.ones;
            }
            tempArr.push(tempObj);
        }
        for(var j = minOnes; j <= maxOnes; j++){
            tempArr.forEach(function(item){
                if(item.ones === j){
                    newArr.push(item.num);
                }
            });
        }
        result = newArr;
    } else {
        result = arr;
    }
    return result;
}

