const sortArray = (arr) => {
    let answer = [];
  let ones = [];
  let zeros = [];
  let len = arr.length;
  for(let i = 0; i < len; i++){
    if(arr[i] <= 0){
      zeros.push(arr[i]);
    }else{
      ones.push(arr[i]);
    }
  }
  //sorting the ones array
  let onesLen = ones.length;
  for(let i = 0; i < onesLen; i++){
    let item = ones[i];
    let bin = item.toString(2);
    let oneCnt = bin.split('').reduce((a, b) => +a + +b);
    ones[i] = {'bin': bin, 'num': item, 'oneCnt': oneCnt};
  }
  ones.sort((a, b) => {
    if(a.oneCnt === b.oneCnt){
      return a.num - b.num;
    }else{
      return a.oneCnt - b.oneCnt;
    }
  });
  let len2 = ones.length;
  for(let i = 0; i < len2; i++){
    answer.push(ones[i].num);
  }
  answer = answer.concat(zeros);
  return answer;
}

