const removeVowels = (text) => {
    //if the text is empty
	if(text.length === 0){
		return '';
	}
	//if the text is just one letter
	if(text.length === 1){
		//if the text is not a vowel then return it
		if(text !== 'a' && text !== 'e' && text !== 'i' && text !== 'o' && text !== 'u'){
			return text;
		}
		//if the text is a vowel return ''
		else{
			return '';
		}
	}
	//if the text has more than one letter
	else{
		//if the first letter is not a vowel, then return it + remove_vowels function on the next letter
		if(text[0] !== 'a' && text[0] !== 'e' && text[0] !== 'i' && text[0] !== 'o' && text[0] !== 'u'){
			return text[0] + remove_vowels(text.slice(1));
		}
		//if the first letter is a vowel, then return remove_vowels function on the next letter
		else{
			return remove_vowels(text.slice(1));
		}
	}
}

