    var long,short;
  if(a.length > b.length){
    long = a;
    short = b;
  }else{
    long = b;
    short = a;
  }
  var short_length = short.length;
  var short_first_letter = short[0];
  for(var i = 0; i < long.length; i++){
    if(long[i] == short_first_letter){
      if(long.substring(i,i+short_length) == short){
        return true;
      }
    }
  }
  var short_last_letter = short[short_length-1];
  for(var i = 0; i < long.length; i++){
    if(long[i] == short_last_letter){
      if(long.substring(i-short_length+1,i+1) == short){
        return true;
      }
    }
  }
  return false;
}

