                is_in_group = true;
                group = paren;
            }
        } else if (paren === ')') {
            if (is_in_group) {
                group += paren;
                groups.push(group);
                is_in_group = false;
            } else {
                throw new Error('Unbalanced right parenthesis at index ' + i);
            }
        }
    }
    if (is_in_group) {
        throw new Error('Unbalanced left parenthesis at index ' + i);
    }
    return groups;
}

