const circularShift = (x, shift) => {
    // convert integer to string and split it into an array of chars
	var str = '' + x;
	var a = str.split('');
	// create new array for our result
	var b = [];
	// iterate over the chars from original array and push them to new array
	for (var i = 0; i < a.length; i++) {
		// if our counter reaches the end of array, wrap around
		if(i + shift >= a.length){
			b.push(a[i + shift - a.length]);
		}
		// otherwise just push character from current position
		else{
			b.push(a[i + shift]);
		}
	}
	// join array into a string, return it
	return b.join('');
}

