const solve = (s) => {
    //code
    if(s.length === 0){
        return "";
    }
    else{
        let firstHalf = "";
        let secondHalf = "";
        let midOfString = s.length / 2;
        for(let i = 0; i < s.length; i++){
            if(i < midOfString){
                firstHalf += s[i];
            }
            else{
                secondHalf += s[i];
            }
        }
        let result = "";
        for(let i = secondHalf.length - 1; i >= 0; i--){
            result += secondHalf[i];
        }
        return result + firstHalf;
    }
}

