const histogram = (test) => {
    //Split the string into array of chars
    let arr = test.split(' ');
    let ocurrence = {};

    //Go through each char and add it to ocurrence object if it doesn't exist, or increment the count if it does
    for(let i = 0; i < arr.length; i++){
        if(!ocurrence[arr[i]]){
            ocurrence[arr[i]] = 1;
        }else{
            ocurrence[arr[i]] += 1;
        }
    }

    let maxValue = Math.max(...Object.values(ocurrence));
    let maxKeys = [];

    //Add to maxKeys all keys whose values are the same as maxValue
    for(let key in ocurrence){
        if(ocurrence[key] === maxValue){
            maxKeys.push(key);
        }
    }

    //Go through maxKeys and delete every key that is not a maxKey
    for(let key in ocurrence){
        if(!maxKeys.includes(key)){
            delete ocurrence[key];
        }
    }

    return ocurrence;
}

